// Keep rising related queries and topics, one row each.
const today = new Date().toISOString().slice(0, 10);
return $input.all()
  .map((item) => item.json)
  .filter((r) => r.found !== false && (r.rowType === 'related_query' || r.rowType === 'related_topic') && r.listType === 'rising')
  .map((r) => ({
    json: {
      date: today,
      topic: r.search,
      kind: r.rowType === 'related_query' ? 'query' : 'topic',
      risingSearch: r.relatedQuery ?? r.topicTitle,
      growth: r.risingPercent == null ? 'Breakout' : `+${r.risingPercent}%`,
      rank: r.rank,
      country: r.geo,
      googleTrends: r.trendsUrl,
    },
  }));
